public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || start.length == 0 || end == null || end.length == 0 || n <= 0) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) {
            continue; // ignore invalid edges
        }
        int a = p[0];
        int b = p[1];
        if (a < 0 || a >= n || b < 0 || b >= n) {
            continue; // skip out-of-range edges
        }
        adj[a].add(b);
        adj[b].add(a);
    }
    // BFS from start to end
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(s);
    visited[s] = true;
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == t) {
            return "can be travelled";
        }
        for (int next : adj[curr]) {
            if (!visited[next]) {
                visited[next] = true;
                queue.offer(next);
            }
        }
    }
    return "cannot be travelled";
}

